# ============== БАЗОВЫЕ ПАПКИ ПРИЛОЖЕНИЯ (portable-aware) ==============
# _app_base_dir() — папка для EXTERNAL данных (config_local.py / config.ini, runtime_settings.json,
#                   backups/, .ssh/). В dev-режиме = папка с dashboard.py. В portable-режиме
#                   (PyInstaller frozen) = папка с exe. Юзер кладёт config_local.py рядом с exe.
# _resource_dir() — папка для INTERNAL bundled-ресурсов (favicon, bootstrap-скрипты).
#                   В dev = папка с dashboard.py. В frozen-onefile = sys._MEIPASS (temp extract).
def _app_base_dir():
    if getattr(sys, "frozen", False):
        return os.path.dirname(os.path.abspath(sys.executable))
    return os.path.dirname(os.path.abspath(__file__))

def _resource_dir():
    if getattr(sys, "frozen", False):
        return getattr(sys, "_MEIPASS", os.path.dirname(os.path.abspath(sys.executable)))
    return os.path.dirname(os.path.abspath(__file__))

# Frozen режим (portable exe):
#   1. Добавляем папку рядом с exe в sys.path → внешний config_local.py перебивает stub.
#   2. Авто-создание config.ini из template при первом запуске.
#   3. Если config_local.py нет рядом с exe → собираем sham-модуль из вшитого example.
#   4. config.ini ВСЕГДА overlay поверх config_local (даёт быструю настройку port/ssh/auth
#      без правки .py файла).
_ext_dir = None
_ext_ini = None
if getattr(sys, "frozen", False):
    _ext_dir = _app_base_dir()
    if _ext_dir not in sys.path:
        sys.path.insert(0, _ext_dir)
    _ext_py = os.path.join(_ext_dir, "config_local.py")
    _ext_ini = os.path.join(_ext_dir, "config.ini")

    # Авто-создание config.ini из template. Если config_local.py есть рядом с exe —
    # заполняем ini его реальными значениями (port/ssh/auth) вместо placeholders.
    if not os.path.isfile(_ext_ini):
        _template_path = os.path.join(_resource_dir(), "config.ini.template")
        if os.path.isfile(_template_path):
            try:
                with open(_template_path, "r", encoding="utf-8-sig") as _ft:
                    _tmpl_text = _ft.read()
                # Если рядом есть config_local.py — снимаем с него snapshot ini-полей
                if os.path.isfile(_ext_py):
                    import runpy as _runpy_snap
                    try:
                        _local_ns = _runpy_snap.run_path(_ext_py)
                    except Exception:
                        _local_ns = {}
                    _replacements = [
                        ("port = 5000",                       "port = " + str(_local_ns.get("DASHBOARD_PORT", 5000))),
                        ("host = 192.168.1.1",                "host = " + str(_local_ns.get("KEENETIC_HOST", "192.168.1.1"))),
                        ("port = 222",                        "port = " + str(_local_ns.get("KEENETIC_PORT", 222))),
                        ("user = root",                       "user = " + str(_local_ns.get("KEENETIC_USER", "root"))),
                        ("key = id_keenetic",                 "key = " + os.path.basename(str(_local_ns.get("KEENETIC_SSH_KEY", "id_keenetic")))),
                        ("CHANGE_ME_TO_RANDOM_PASSWORD",      str(_local_ns.get("PASSWORD", "CHANGE_ME_TO_RANDOM_PASSWORD"))),
                        ("CHANGE_ME_TO_RANDOM_32CHAR_STRING", str(_local_ns.get("SECRET_KEY", "CHANGE_ME_TO_RANDOM_32CHAR_STRING"))),
                        ("CHANGE_ME_TO_RANDOM_TOKEN",         str(_local_ns.get("SUBSCRIPTION_TOKEN", "CHANGE_ME_TO_RANDOM_TOKEN"))),
                    ]
                    for _old, _new in _replacements:
                        _tmpl_text = _tmpl_text.replace(_old, _new)
                with open(_ext_ini, "w", encoding="utf-8") as _fo:
                    _fo.write(_tmpl_text)
                sys.stderr.write("\n⚙ Создан " + _ext_ini + ("" if not os.path.isfile(_ext_py) else " (заполнен из config_local.py)") + "\n\n")
            except Exception as _ex:
                sys.stderr.write("WARNING: не удалось создать config.ini: " + str(_ex) + "\n")

    # Если config_local.py нет рядом с exe — собираем sham из вшитого example
    if not os.path.isfile(_ext_py):
        import runpy as _runpy
        import types as _types_mod
        _example_path = os.path.join(_resource_dir(), "config_local.example.py")
        _ns = _runpy.run_path(_example_path) if os.path.isfile(_example_path) else {}
        _sham = _types_mod.ModuleType("config_local")
        for _k, _v in _ns.items():
            if not _k.startswith("__"):
                setattr(_sham, _k, _v)
        sys.modules["config_local"] = _sham

try:
    import config_local as cfg
except ImportError:
    sys.stderr.write(
        "\nERROR: config_local.py не найден.\n"
        "  - В portable-режиме положи config.ini рядом с exe (template создаётся автоматически).\n"
        "  - В dev-режиме скопируй config_local.example.py -> config_local.py и заполни.\n\n"
    )
    sys.exit(1)

# Portable: автокопия SSH-ключа в папку рядом с exe (ДО ini overlay, чтобы захватить
# оригинальный absolute path из config_local.py — после overlay он переписывается на
# _ext_dir/<basename>).
if _ext_dir and getattr(cfg, "KEENETIC_SSH_KEY", None):
    _orig_key = cfg.KEENETIC_SSH_KEY
    if os.path.isabs(_orig_key) and os.path.isfile(_orig_key):
        _local_key = os.path.join(_ext_dir, os.path.basename(_orig_key))
        if os.path.abspath(_orig_key) != os.path.abspath(_local_key) and not os.path.isfile(_local_key):
            try:
                import shutil as _shutil_key
                _shutil_key.copy2(_orig_key, _local_key)
                sys.stderr.write("\n⚙ SSH-ключ скопирован в " + _local_key + " (для портабл-переноса)\n")
                cfg.KEENETIC_SSH_KEY = _local_key
                # OpenSSH под Windows отказывается работать с ключом если ACL слишком открыты
                # ("UNPROTECTED PRIVATE KEY FILE"). Ужесточаем: только текущий пользователь — read.
                # Если icacls недоступен или fail — юзер увидит warning при попытке коннекта.
                if sys.platform == "win32":
                    try:
                        import subprocess as _sp_acl
                        import getpass as _gp_acl
                        _sp_acl.run(
                            ["icacls", _local_key, "/inheritance:r", "/grant:r", _gp_acl.getuser() + ":R"],
                            capture_output=True, timeout=10, check=False,
                        )
                    except Exception:
                        pass
            except Exception as _ex:
                sys.stderr.write("WARNING: не удалось скопировать SSH-ключ: " + str(_ex) + "\n")

# Frozen + config.ini → overlay простых полей поверх любого config_local.
# Это позволяет менять port/ssh/auth через ini без правки .py файла.
if _ext_ini and os.path.isfile(_ext_ini):
    import configparser as _cp_mod
    _cp = _cp_mod.ConfigParser()
    _cp.read(_ext_ini, encoding="utf-8-sig")  # utf-8-sig игнорит BOM от PowerShell Set-Content
    if _cp.has_section("server"):
        if _cp.has_option("server", "port"):
            cfg.DASHBOARD_PORT = _cp.getint("server", "port")
    if _cp.has_section("ssh"):
        if _cp.has_option("ssh", "host"):
            cfg.KEENETIC_HOST = _cp.get("ssh", "host")
        if _cp.has_option("ssh", "port"):
            cfg.KEENETIC_PORT = _cp.getint("ssh", "port")
        if _cp.has_option("ssh", "user"):
            cfg.KEENETIC_USER = _cp.get("ssh", "user")
        if _cp.has_option("ssh", "key"):
            _kn = _cp.get("ssh", "key")
            cfg.KEENETIC_SSH_KEY = _kn if os.path.isabs(_kn) else os.path.join(_ext_dir, _kn)
    if _cp.has_section("auth"):
        if _cp.has_option("auth", "username"):
            cfg.USERNAME = _cp.get("auth", "username")
        if _cp.has_option("auth", "password"):
            cfg.PASSWORD = _cp.get("auth", "password")
        if _cp.has_option("auth", "secret_key"):
            cfg.SECRET_KEY = _cp.get("auth", "secret_key")
        if _cp.has_option("auth", "subscription_token"):
            cfg.SUBSCRIPTION_TOKEN = _cp.get("auth", "subscription_token")

import threading as _threading

# ============== ВЕРСИЯ ПАНЕЛИ ==============
# Hardcoded fallback. Обновляется руками при каждом release (см. CONTRIBUTING.md).
# Динамически пытаемся прочитать через `git describe --tags --abbrev=0` —
# если в репо есть свежий tag (например юзер на main после моего push), увидит его.
# Если git недоступен (например запуск из zip) — fallback на _VERSION_FALLBACK.
_VERSION_FALLBACK = "1.0.84"


def _find_git():
    """Путь к git.exe: сначала PATH, иначе стандартные места установки. Важно для
    SYSTEM-процесса (Task Scheduler): у него PATH часто БЕЗ git → git describe молча
    падал и версия откатывалась на устаревший _VERSION_FALLBACK (симптом: дом-панель
    от SYSTEM показывала старую версию, хотя репо обновлён)."""
    import shutil
    g = shutil.which("git")
    if g:
        return g
    for p in (r"C:\Program Files\Git\cmd\git.exe",
              r"C:\Program Files\Git\bin\git.exe",
              r"C:\Program Files (x86)\Git\cmd\git.exe"):
        if os.path.exists(p):
            return p
    return "git"


def get_dashboard_version():
    """Версия панели. Сначала git describe (свежее), потом fallback на константу.
    Кэшируется на 60 сек — git вызов недешёвый."""
    now = _time_mod.time()
    cached = getattr(get_dashboard_version, "_cache", None)
    if cached and now - cached[1] < 60:
        return cached[0]
    version = _VERSION_FALLBACK
    try:
        result = subprocess.run(
            [_find_git(), "describe", "--tags", "--abbrev=0"],
            cwd=_resource_dir(),
            capture_output=True, text=True, timeout=2,
        )
        if result.returncode == 0 and result.stdout:
            # Вынимаем ТОЛЬКО номер версии (напр. "1.4.3") regex'ом, а не берём весь
            # stdout. Иначе в строку версии протекает посторонний мусор: сторонние DLL
            # (антивирус / EDR-хук) умеют писать диагностику дизассемблера ("ANOMALY:
            # use of REX.w ...") прямо в stdout дочернего процесса git — .strip() его
            # не убирает, и он вылезал в шапку панели рядом с версией.
            m = re.search(r'\d+\.\d+\.\d+', result.stdout)
            if m:
                version = m.group(0)
    except Exception:
        pass
    get_dashboard_version._cache = (version, now)
    return version

# ============== RUNTIME SETTINGS (overrides поверх config_local.py) ==============
# Хранятся отдельным JSON чтобы при обновлении dashboard.py не сбрасывались.
# Перезаписывают атрибуты cfg-модуля → существующий код cfg.KEENETIC_* работает без правок.
RUNTIME_SETTINGS_FILE = os.path.join(_app_base_dir(), "runtime_settings.json")
_RUNTIME_LOCK = _threading.Lock()
# Сериализует read-modify-write watchdog.config: при двойном «Сохранить» (PRIMARY сразу за
# FAILOVER) без него два запроса могут прочитать конфиг одновременно и один затереть правку
# другого. Лок in-process (хватает для threaded-сервера; на один pythonw-процесс — то что нужно).
_WATCHDOG_CFG_LOCK = _threading.Lock()

# key в runtime.keenetic → attr в cfg-модуле. KEENETIC_PORT — int, остальные str.
KEENETIC_RUNTIME_KEYS = [
    ("host",           "KEENETIC_HOST",           "str"),
    ("port",           "KEENETIC_PORT",           "int"),
    ("user",           "KEENETIC_USER",           "str"),
    ("ssh_key",        "KEENETIC_SSH_KEY",        "str"),
    ("xray_configs",   "KEENETIC_XRAY_CONFIGS",   "str"),
    ("xray_bak_dir",   "KEENETIC_XRAY_BAK_DIR",   "str"),
    ("watchdog_state", "KEENETIC_WATCHDOG_STATE", "str"),
    ("watchdog_log",   "KEENETIC_WATCHDOG_LOG",   "str"),
]

def load_runtime_settings():
    with _RUNTIME_LOCK:
        if not os.path.exists(RUNTIME_SETTINGS_FILE):
            return {}
        try:
            with open(RUNTIME_SETTINGS_FILE, encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return {}

def save_runtime_settings(data):
    with _RUNTIME_LOCK:
        with open(RUNTIME_SETTINGS_FILE, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)

def apply_runtime_overrides():
    """Перезаписать атрибуты cfg значениями из runtime_settings.json."""
    rt = load_runtime_settings()
    kn = rt.get("keenetic", {}) if isinstance(rt.get("keenetic"), dict) else {}
    for rt_key, cfg_attr, typ in KEENETIC_RUNTIME_KEYS:
        if rt_key in kn and kn[rt_key] not in ("", None):
            try:
                val = int(kn[rt_key]) if typ == "int" else str(kn[rt_key])
                setattr(cfg, cfg_attr, val)
            except (ValueError, TypeError):
                pass

def get_keenetic_settings_merged():
    """Текущее эффективное состояние SSH-настроек роутера для UI.
    Возвращает {current: {...}, overridden: {key: bool}}.
    Если overridden[key]=False — значение пришло из config_local.py (показать как «по умолчанию»).
    """
    rt = load_runtime_settings().get("keenetic", {}) or {}
    out = {"current": {}, "overridden": {}}
    for rt_key, cfg_attr, _typ in KEENETIC_RUNTIME_KEYS:
        out["current"][rt_key] = getattr(cfg, cfg_attr, None)
        out["overridden"][rt_key] = rt_key in rt and rt[rt_key] not in ("", None)
    return out

# Применить overrides при импорте, до создания Flask-приложения
apply_runtime_overrides()

