# ============== SELF-HEALING / DIAGNOSE / AUTO-REPAIR (v1.5.1) ==============
# Юзер не должен лезть в SSH чтобы починить «xkeen не запускается». Эта секция:
# 1. /api/xkeen/diagnose — запускает 7+ проверок, возвращает структуру { checks: [...], can_fix: [...] }
# 2. /api/xkeen/auto-fix — выполняет конкретный fix (set-primary-direct, restart-xkeen, regen-routing, ...)
# Дома видим всё в UI секции «🚑 Восстановление и диагностика».


@app.route("/api/xkeen/diagnose", methods=["GET"])
@requires_auth
def api_xkeen_diagnose():
    """Запустить серию проверок состояния XKeen на роутере. Возвращает:
        { ok: bool, checks: [ {id, label, ok, severity, detail, fix_id, fix_label, fix_explain} ] }
    severity: critical | warning | info
    fix_id: ID auto-fix (передаётся в /api/xkeen/auto-fix), None если автоматического fix нет.
    """
    checks = []
    ansi_re = re.compile(r'\x1b\[[0-9;?]*[a-zA-Z]')

    def _add(check_id, label, ok, severity, detail, fix_id=None, fix_label=None, fix_explain=None):
        checks.append({
            "id": check_id, "label": label, "ok": ok, "severity": severity,
            "detail": (detail or "")[:1500],
            "fix_id": fix_id, "fix_label": fix_label, "fix_explain": fix_explain,
        })

    # ---- 1. Xray binary version + arch ----
    r = keenetic_ssh("/opt/sbin/xray version 2>&1 | head -3", timeout=10)
    xray_out = ansi_re.sub('', r.get("stdout") or "")
    is_xray_ok = r["ok"] and "Xray" in xray_out and "SIGSEGV" not in xray_out
    arch = ""
    if "linux/mips" in xray_out:
        arch = "mips32le" if "mipsle" in xray_out else "mips32 (BE — возможно неверная арх!)"
    _add(
        "xray_binary", "Xray binary доступен", is_xray_ok,
        "critical" if not is_xray_ok else "info",
        xray_out + (f"\n\nАрхитектура: {arch}" if arch else ""),
        fix_id=None, fix_label=None,
        fix_explain=("Если xray даёт Go runtime crash (SIGSEGV) — это арх mismatch. Нужно вручную скачать "
                     "Xray-linux-mips32le.zip с XTLS/Xray-core releases (см. Help)." if not is_xray_ok else None),
    )

    # ---- 2. xkeen process status ----
    r = keenetic_ssh("xkeen -status 2>&1", timeout=10)
    status_out = ansi_re.sub('', (r.get("stdout") or "") + (r.get("stderr") or ""))
    is_running = "запущен" in status_out and "не запущен" not in status_out
    _add(
        "xkeen_running", "xkeen (xray) запущен", is_running,
        "critical" if not is_running else "info",
        status_out,
        fix_id="restart_xkeen" if not is_running else None,
        fix_label="🔄 Запустить xkeen" if not is_running else None,
        fix_explain=("xkeen -restart перезапустит xray. Если после рестарта снова "
                     "«не запущен» — смотрим логи xray и валидность конфигов (см. ниже)." if not is_running else None),
    )

    # ---- 3. xray config validity (test mode) ----
    # v1.0.52 фикс ложного critical: ОБЯЗАТЕЛЬНО задаём XRAY_LOCATION_ASSET=/opt/etc/xray/dat —
    # иначе xray ищет geosite/geoip .dat в /opt/sbin/ (default), не находит и ложно ругается
    # «failed to open geosite_v2fly.dat» при ЛЮБОМ ext:geosite_v2fly.dat:* правиле (хотя рабочий
    # xray, запущенный XKeen с этим env, валиден). И НЕ пайпим через tail (тогда $? = tail's, а не
    # xray; + при многих outbound'ах «Configuration OK» вылетал за tail-окно). Берём полный вывод:
    # валидно = xray exit 0 ИЛИ присутствует «Configuration OK».
    r = keenetic_ssh("XRAY_LOCATION_ASSET=/opt/etc/xray/dat /opt/sbin/xray run -test -confdir /opt/etc/xray/configs 2>&1", timeout=20)
    test_out_full = ansi_re.sub('', r.get("stdout") or "")
    is_config_valid = (r.get("code") == 0) or ("Configuration OK" in test_out_full)
    # detail: последние непустые строки (вердикт в конце) — иначе UI заливают [Info] prepend-строки
    _tl = [ln for ln in test_out_full.splitlines() if ln.strip()]
    test_out = "\n".join(_tl[-12:]) if _tl else test_out_full
    _add(
        "config_valid", "xray-конфиги валидны", is_config_valid,
        "critical" if not is_config_valid else "info",
        test_out,
        fix_id="regen_routing" if not is_config_valid else None,
        fix_label="🔧 Перегенерить routing" if not is_config_valid else None,
        fix_explain=("xray-конфиги невалидны. Самая частая причина — битый routing.json (пустой "
                     "outboundTag или ссылка на несуществующий outbound). Перегенерация через watchdog "
                     "обычно помогает." if not is_config_valid else None),
    )

    # ---- watchdog.sh: версия на роутере vs встроенная в панель ----
    _wd_remote_ver = 0
    r = keenetic_ssh("head -40 /opt/etc/xray/watchdog.sh 2>/dev/null", timeout=8)
    if r["ok"]:
        _wd_remote_ver = _parse_watchdog_version(r.get("stdout", ""))
    _wd_local_ver = 0
    _wd_local_path = _bootstrap_find("watchdog.sh.cur")
    if _wd_local_path and os.path.exists(_wd_local_path):
        try:
            with open(_wd_local_path, "rb") as _f:
                _wd_local_ver = _parse_watchdog_version(_f.read().decode("utf-8", "replace"))
        except Exception:
            pass
    _wd_ok = (_wd_remote_ver > 0) and (_wd_remote_ver >= _wd_local_ver)
    if _wd_remote_ver == 0:
        _wd_detail = "Не удалось определить версию watchdog на роутере (роутер недоступен или /opt/etc/xray/watchdog.sh отсутствует)."
    elif _wd_ok:
        _wd_detail = f"На роутере: v{_wd_remote_ver}\nВстроенная в панель: v{_wd_local_ver}\n✅ Актуальна — на роутере новейший safety-watchdog (health-check + авто-откат)."
    else:
        _wd_detail = (f"На роутере: v{_wd_remote_ver}\nВстроенная в панель: v{_wd_local_ver}\n"
                      f"⚠ Устарела. Обновится АВТОМАТИЧЕСКИ при следующем «Сохранить» в панели "
                      f"(любая настройка → панель сама зальёт свежий watchdog перед применением).")
    _add(
        "watchdog_version", "Версия watchdog на роутере", _wd_ok,
        "info" if _wd_ok else "warning",
        _wd_detail,
        fix_id=None, fix_label=None,
        fix_explain=(None if _wd_ok else
                     "Нажми любое «Сохранить» (например PRIMARY в «Основном») — авто-синк (v1.0.50+) сам поднимет watchdog до актуальной версии перед применением."),
    )

    # ---- 4. watchdog.config: PRIMARY_TAG не пустой ----
    r = keenetic_ssh("grep '^PRIMARY_TAG=' /opt/etc/xray/watchdog.config 2>/dev/null", timeout=5)
    primary_line = (r.get("stdout") or "").strip()
    primary_tag = ""
    if "=" in primary_line:
        primary_tag = primary_line.split("=", 1)[1].strip().strip('"')
    has_primary = bool(primary_tag)
    _add(
        "watchdog_primary", "PRIMARY_TAG задан в watchdog.config", has_primary,
        "critical" if not has_primary else "info",
        primary_line or "(не найдено в watchdog.config)",
        fix_id="set_primary_direct" if not has_primary else None,
        fix_label="🔧 Установить PRIMARY = direct" if not has_primary else None,
        fix_explain=("PRIMARY_TAG пустой → watchdog сгенерит routing с outboundTag='' → xray валится. "
                     "Установим PRIMARY=direct (трафик через провайдера). Можно потом сменить через UI "
                     "в секции «🎯 Основное и резервное подключение»." if not has_primary else None),
    )

    # ---- 5. direct + block в outbounds ----
    r = keenetic_ssh("grep -oE '\"tag\": *\"(direct|block)\"' /opt/etc/xray/configs/04_outbounds.json 2>/dev/null", timeout=5)
    out_text = r.get("stdout") or ""
    has_direct = "direct" in out_text
    has_block = "block" in out_text
    has_both = has_direct and has_block
    _add(
        "outbounds_defaults", "direct + block в 04_outbounds.json", has_both,
        "critical" if not has_both else "info",
        f"direct: {'✅' if has_direct else '❌'}\nblock: {'✅' if has_block else '❌'}\n{out_text}",
        fix_id="bootstrap_outbounds" if not has_both else None,
        fix_label="🔧 Добавить direct + block" if not has_both else None,
        fix_explain=("Без direct/block в outbounds — виртуальный канал «🌐 Напрямую» не работает, "
                     "BLOCK_DOMAINS не работают. Auto-fix добавит их (existing outbounds останутся "
                     "нетронутыми)." if not has_both else None),
    )

    # ---- 6. JSON syntax: 05_routing.json ----
    r = keenetic_ssh(
        "sed 's|^[[:space:]]*//.*$||' /opt/etc/xray/configs/05_routing.json | jq empty 2>&1",
        timeout=10,
    )
    routing_json_valid = r["ok"] and not r.get("stdout", "").strip() and not r.get("stderr", "").strip()
    _add(
        "routing_json_valid", "05_routing.json — валидный JSON", routing_json_valid,
        "critical" if not routing_json_valid else "info",
        (r.get("stdout") + r.get("stderr"))[:500] if not routing_json_valid else "OK",
        fix_id="regen_routing" if not routing_json_valid else None,
        fix_label="🔧 Перегенерить routing из template" if not routing_json_valid else None,
        fix_explain=("routing.json содержит синтаксическую ошибку JSON. Watchdog v9+ умеет валидировать "
                     "перед записью, но если файл повреждён вручную — перегенерация исправит." if not routing_json_valid else None),
    )

    # ---- 7. Cron-задача watchdog ----
    r = keenetic_ssh("crontab -l 2>/dev/null | grep -F '/opt/etc/xray/watchdog.sh'", timeout=5)
    has_cron = bool((r.get("stdout") or "").strip())
    _add(
        "cron_watchdog", "Cron-задача watchdog активна", has_cron,
        "warning" if not has_cron else "info",
        (r.get("stdout") or "(не найдена)").strip(),
        fix_id="bootstrap_cron" if not has_cron else None,
        fix_label="🔧 Добавить cron-задачу" if not has_cron else None,
        fix_explain=("Без cron-задачи watchdog не будет автоматически проверять каналы и переключаться "
                     "при падении. xray запустится один раз, но failover не сработает." if not has_cron else None),
    )

    # ---- 8. Watchdog log: последние ошибки ----
    r = keenetic_ssh("tail -20 /opt/var/log/xray/watchdog.log 2>/dev/null | grep -E 'ERROR|WARN' | tail -5", timeout=5)
    recent_errors = (r.get("stdout") or "").strip()
    no_errors = not recent_errors
    _add(
        "watchdog_no_errors", "Watchdog без свежих ошибок", no_errors,
        "warning" if not no_errors else "info",
        recent_errors or "(ошибок не найдено)",
        fix_id=None, fix_label=None,
        fix_explain=("В логе watchdog есть свежие ошибки/предупреждения. Это может быть нормально "
                     "(например VPN-канал временно недоступен), но если повторяется — стоит разобраться." if not no_errors else None),
    )

    # ---- 9. v1.6.1: geoip.dat содержит используемые GeoIP-категории ----
    # Симптом: xray test говорит "code not found in geoip.dat: TELEGRAM" → xkeen уходит в Mixed mode.
    # Причина: стандартный v2fly geoip.dat содержит только страны (cn, ru, us...), сервисов нет.
    # Решение: расширенный geoip.dat от Loyalsoldier (содержит и страны, и сервисы).
    r = keenetic_ssh("grep '^YT_GEOIP_CATEGORIES=' /opt/etc/xray/watchdog.config 2>/dev/null", timeout=5)
    geoip_line = (r.get("stdout") or "").strip()
    geoip_cats = ""
    if "=" in geoip_line:
        geoip_cats = geoip_line.split("=", 1)[1].strip().strip('"')
    clean_geoip = re.sub(r'[\s,]+', '', geoip_cats)

    if not clean_geoip:
        _add(
            "geoip_categories", "geoip.dat содержит используемые категории", True,
            "info",
            "GeoIP-категории не настроены (YT_GEOIP_CATEGORIES пуст) — проверка не нужна.",
            fix_id=None, fix_label=None, fix_explain=None,
        )
    else:
        # Проверяем xray test на ошибку "code not found in geoip.dat"
        r = keenetic_ssh("XRAY_LOCATION_ASSET=/opt/etc/xray/dat /opt/sbin/xray run -test -confdir /opt/etc/xray/configs 2>&1 | grep -iE 'code not found in geoip|failed to load GeoIP' | head -3", timeout=20)
        missing_out = ansi_re.sub('', r.get("stdout") or "")
        has_missing = bool(missing_out.strip())
        _add(
            "geoip_categories", "geoip.dat содержит используемые категории", not has_missing,
            "critical" if has_missing else "info",
            missing_out or f"Используемые категории: {geoip_cats}\nxray test прошёл без ошибок 'code not found'.",
            fix_id="install_extended_geoip" if has_missing else None,
            fix_label="📥 Установить расширенный geoip.dat" if has_missing else None,
            fix_explain=(
                "В geoip.dat нет нужной категории (например telegram). Стандартный v2fly geoip.dat "
                "содержит только страны (cn, ru, us). Сервисы (telegram, discord) есть в расширенном "
                "geoip.dat от Loyalsoldier/v2ray-rules-dat (~18MB). Auto-fix скачает и установит его, "
                "потом перезапустит xkeen."
            ) if has_missing else None,
        )

    # ---- curl + RCI работают (нужно xkeen-installer для проверки политики) ----
    # Прецедент 2026-05-20: на роутере пропал libnghttp2.so.14 → curl сломан →
    # xkeen -restart падал с «политика не найдена», xray не поднимался.
    # Xray продолжает работать пока его не рестартят — это скрытый баг до первой попытки restart.
    r_curl = keenetic_ssh("curl --version 2>&1 | head -3", timeout=10)
    curl_out = (r_curl.get("stdout") or "") + (r_curl.get("stderr") or "")
    curl_broken = "shared libraries" in curl_out or "cannot open shared object" in curl_out or not r_curl["ok"]
    missing_lib = None
    if curl_broken:
        m = re.search(r"(lib[\w\-\.]+\.so\.\d+)", curl_out)
        if m:
            missing_lib = m.group(1)
    if curl_broken:
        _add(
            "curl_rci_works", "curl + RCI Keenetic работают", False, "critical",
            f"curl сломан или отсутствует библиотека.\nВывод:\n{curl_out[:600]}",
            fix_id="install_libnghttp2",
            fix_label=f"🔧 Переустановить {missing_lib or 'libnghttp2'}",
            fix_explain=(
                "xkeen-installer проверяет политику XKeen через RCI Keenetic "
                "(curl localhost:79/rci/show/ip/policy). Без рабочего curl xkeen думает что "
                "политики нет и пытается работать в fallback-режиме (все клиенты через 80/443), "
                "что конфликтует с Keenetic UI на 443. xray НЕ ЗАПУСКАЕТСЯ при рестарте. "
                "Fix: opkg update + opkg install libnghttp2 --force-reinstall."
            ),
        )
    else:
        # curl работает — проверим что RCI отвечает валидным JSON
        r_rci = keenetic_ssh('curl -kfsS "localhost:79/rci/show/ip/policy" 2>&1 | head -c 200', timeout=8)
        rci_out = r_rci.get("stdout") or ""
        rci_ok = r_rci["ok"] and (rci_out.lstrip().startswith("{") or rci_out.lstrip().startswith("["))
        _add(
            "curl_rci_works", "curl + RCI Keenetic работают", rci_ok,
            "warning" if not rci_ok else "info",
            (curl_out.splitlines()[0] if curl_out else "(curl OK)") + "\nRCI: " +
            (rci_out[:200] if rci_ok else f"⚠ не вернул JSON: {rci_out[:300]}"),
            fix_id=None, fix_label=None, fix_explain=None,
        )

    # ---- Entware GNU tar для миграции ----
    # XKeen-документация использует `tar cvzf ... --exclude=PATH -C /opt .` который работает
    # только с GNU tar. На BusyBox-tar флаг --exclude= не поддержан → миграция через
    # entware_backup.tar.gz падает с tar-help. Проверяем что /opt/bin/tar (Entware-пакет) есть.
    r_etar = keenetic_ssh("[ -x /opt/bin/tar ] && /opt/bin/tar --version 2>&1 | head -1 || echo MISSING", timeout=5)
    etar_out = (r_etar.get("stdout") or "").strip()
    etar_ok = "tar" in etar_out and "MISSING" not in etar_out
    _add(
        "entware_tar", "Entware GNU tar установлен (для миграции)", etar_ok,
        "warning" if not etar_ok else "info",
        etar_out[:200] if etar_out else "(empty)",
        fix_id="install_entware_tar" if not etar_ok else None,
        fix_label="📥 Установить Entware GNU tar" if not etar_ok else None,
        fix_explain=(
            "Без /opt/bin/tar миграция через entware_backup.tar.gz работает на ограниченном "
            "BusyBox-fallback. Auto-fix поставит полноценный GNU tar через opkg."
        ) if not etar_ok else None,
    )

    # Общий статус — ok если все critical-проверки прошли
    overall_ok = all(c["ok"] or c["severity"] != "critical" for c in checks)
    failed_critical = [c for c in checks if not c["ok"] and c["severity"] == "critical"]

    return jsonify({
        "ok": overall_ok,
        "checks": checks,
        "summary": {
            "total": len(checks),
            "passed": sum(1 for c in checks if c["ok"]),
            "failed_critical": len(failed_critical),
            "failed_warning": sum(1 for c in checks if not c["ok"] and c["severity"] == "warning"),
        },
    })


_TEST_SOCKS_FILE = "06_socks_test.json"
_TEST_SOCKS_PORT = 10809
_TEST_SOCKS_USER = "diag"
# Тест-узел (socks-инбаунд для сравнения «через outbound») — ДИАГНОСТИЧЕСКИЙ и НЕ должен
# жить вечно: если 06_socks_test.json забыть на роутере, он способен поломать нормальный
# роутинг (был инцидент 2026-05-23 — instagram и «почти любой сайт» отдавали мусор). Поэтому
# узел самоуничтожается НА РОУТЕРЕ через _TEST_SOCKS_TTL сек (не зависит от дашборда/браузера).
_TEST_SOCKS_TTL = 600  # 10 минут — хватает посравнивать, но роутер чинит себя сам
_TEST_SOCKS_SD_DEADLINE = "/tmp/socks_test_sd.deadline"
_TEST_SOCKS_SD_LOG = "/tmp/socks_test_sd.log"


def _test_socks_path():
    return f"{cfg.KEENETIC_XRAY_CONFIGS}/{_TEST_SOCKS_FILE}"


def _test_socks_read():
    """(user, pass, outbound_tag) из 06_socks_test.json на роутере, или (None, None, None)."""
    try:
        data = keenetic_load_json(_test_socks_path())
    except Exception:
        data = None
    if not data:
        return None, None, None
    try:
        inb = next(i for i in data.get("inbounds", []) if i.get("tag") == "socks-test")
        acct = ((inb.get("settings") or {}).get("accounts") or [{}])[0]
        rule = next(r for r in (data.get("routing", {}) or {}).get("rules", [])
                    if "socks-test" in (r.get("inboundTag") or []))
        return acct.get("user"), acct.get("pass"), rule.get("outboundTag")
    except Exception:
        return None, None, None


def _test_socks_proxy_url():
    """socks5h://user:pass@<router>:<port> для прогона проверки через тест-узел; иначе (None, None)."""
    user, pw, tag = _test_socks_read()
    if not user or not tag:
        return None, None
    from urllib.parse import quote
    auth = f"{quote(user, safe='')}:{quote(pw or '', safe='')}@" if pw else ""
    return f"socks5h://{auth}{cfg.KEENETIC_HOST}:{_TEST_SOCKS_PORT}", tag


def _test_socks_run_bg(script):
    """Прогнать многострочный sh-скрипт на роутере через base64-обёртку (без головной боли
    с экранированием вложенных кавычек/переносов — проверенный паттерн)."""
    import base64 as _b64
    b64 = _b64.b64encode(script.encode("utf-8")).decode("ascii")
    return keenetic_ssh(f"echo {b64} | base64 -d | sh", timeout=15)


def _test_socks_arm_selfdestruct(ttl=_TEST_SOCKS_TTL):
    """🛡 КЛЮЧЕВАЯ защита от footgun'а. Вооружить на РОУТЕРЕ авто-удаление 06_socks_test.json
    через ttl секунд. Самоуничтожение идёт НА РОУТЕРЕ (nohup + sleep), поэтому НЕ зависит ни
    от дашборда, ни от браузера, ни от чего-либо внешнего — роутер чинит себя сам, даже если
    юзер забыл нажать «убрать» / закрыл вкладку / дашборд упал.

    Координация через файл-дедлайн: каждый provision вооружает свой таймер и пишет новый
    дедлайн; сработавший таймер сверяет now>=deadline И что дедлайн ещё существует — поэтому
    при нескольких provision'ах реально срабатывает только ПОСЛЕДНИЙ (без лишних рестартов),
    а после явного «убрать» (дедлайн удалён) pending-таймеры ничего не трогают."""
    path = _test_socks_path()
    script = (
        f'DL=$(($(date +%s)+{ttl}))\n'
        f'echo "$DL" > {_TEST_SOCKS_SD_DEADLINE}\n'
        f"nohup sh -c 'sleep {ttl}; "
        f'now=$(date +%s); dl=$(cat {_TEST_SOCKS_SD_DEADLINE} 2>/dev/null) || dl=; '
        f'if [ -n "$dl" ] && [ "$now" -ge "$dl" ]; then '
        f'rm -f {path} {path}.bak-* {_TEST_SOCKS_SD_DEADLINE}; /opt/sbin/xkeen -restart; '
        f"fi' >{_TEST_SOCKS_SD_LOG} 2>&1 &\n"
    )
    return _test_socks_run_bg(script)


def _test_socks_deprovision():
    """Немедленно убрать тест-узел: снять дедлайн (чтобы pending-таймеры самоуничтожения
    ничего не трогали), удалить 06_socks_test.json и перезапустить xkeen в фоне (nohup —
    HTTP-запрос не висит). Идемпотентно (rm -f безопасен когда файла уже нет)."""
    path = _test_socks_path()
    script = (
        f'rm -f {_TEST_SOCKS_SD_DEADLINE} {path} {path}.bak-*\n'
        f'nohup /opt/sbin/xkeen -restart >{_TEST_SOCKS_SD_LOG} 2>&1 &\n'
    )
    return _test_socks_run_bg(script)


_RU_TLD_RE = re.compile(r"\.(?:ru|su|xn--p1ai|рф)$", re.IGNORECASE)


def _domain_in_list(host, domain_list):
    """True (и какой именно домен совпал) если host == d ИЛИ host — поддомен d."""
    h = (host or "").lower().strip(".")
    for d in (domain_list or []):
        d = (d or "").lower().strip(".")
        if d and (h == d or h.endswith("." + d)):
            return d
    return None


def _channel_for_domain(host, tg):
    """В какой канал попадёт домен ПО ПРЕСЕТАМ (watchdog.config). Приоритет = как в watchdog:
    BLOCK > DIRECT(список) > RU-домен(.ru/.su/.рф) > AI > YT > FOREIGN > IPv6 > PRIMARY (по умолчанию).
    ⚠ Geo-категории (ext:geosite:...) НЕ учитываются (на хосте панели нет geo-БД) — домен,
    попадающий в канал ТОЛЬКО через geo-категорию, тут покажется как PRIMARY (см. note во фронте).
    tg = keenetic_get_watchdog_targets(). Возвращает {label, tag, kind, match}."""
    h = (host or "").lower().strip(".")
    m = _domain_in_list(h, tg.get("block_domains"))
    if m: return {"label": "⛔ Блокировать", "tag": "block", "kind": "block", "match": m}
    m = _domain_in_list(h, tg.get("direct_domains"))
    if m: return {"label": "🚫 Напрямую", "tag": "direct", "kind": "direct", "match": m}
    if _RU_TLD_RE.search(h):
        return {"label": "🚫 Напрямую", "tag": "direct", "kind": "direct", "match": "RU-домен (.ru/.su/.рф)"}
    m = _domain_in_list(h, tg.get("ai_domains"))
    if m: return {"label": "🤖 AI", "tag": tg.get("ai_tag"), "kind": "ai", "match": m}
    m = _domain_in_list(h, tg.get("yt_domains"))
    if m: return {"label": "📺 YouTube", "tag": tg.get("yt_tag"), "kind": "yt", "match": m}
    m = _domain_in_list(h, tg.get("foreign_domains"))
    if m: return {"label": "📱 Зарубежные сервисы", "tag": tg.get("foreign_tag"), "kind": "foreign", "match": m}
    m = _domain_in_list(h, tg.get("ipv6_domains"))
    if m: return {"label": "🌐 Через IPv6", "tag": tg.get("ipv6_tag"), "kind": "ipv6", "match": m}
    return {"label": "🌍 Основной (PRIMARY)", "tag": tg.get("primary_tag"), "kind": "primary", "match": None}


# Фейковый IPv4 для IPv6-only / заблокированных-по-IP доменов (RFC 2544 — зарезервирован,
# в реальной маршрутизации не встречается). Клиент коннектится на него → TPROXY ловит →
# xray по SNI понимает домен → шлёт на VPN-сервер, который сам резолвит реальный (IPv6) адрес.
_FAKE_IP_FOR_V6ONLY = "198.18.0.1"
# Строгая валидация домена перед подстановкой в ndmc-команду (защита от инъекции).
_IPHOST_DOMAIN_RE = re.compile(r'^(?=.{1,253}$)([a-z0-9](-?[a-z0-9]){0,62}\.)+[a-z]{2,}$', re.IGNORECASE)


def _doh_has_records(host, rrtype, timeout=4.0):
    """DoH-запрос к Cloudflare за конкретным типом записи (A или AAAA).
    Возвращает True/False (есть ли записи) или None если запрос не удался.
    Идёт НАПРЯМУЮ к публичному DoH → обходит локальный резолвер и наш `ip host`
    (важно: после fake-IP локальный getaddrinfo вернул бы фейк-A и скрыл IPv6-only)."""
    try:
        import requests as _rq
        r = _rq.get("https://cloudflare-dns.com/dns-query",
                    params={"name": host, "type": rrtype},
                    headers={"accept": "application/dns-json"}, timeout=timeout)
        if not r.ok:
            return None
        want = {"A": 1, "AAAA": 28}.get(rrtype)
        return any(a.get("type") == want and a.get("data")
                   for a in (r.json().get("Answer") or []))
    except Exception:  # noqa: BLE001
        return None


def _iphost_entries(timeout=20):
    """Список статических DNS-хостов (ndm `ip host`) на роутере → ([{host, ip}], ok)."""
    r = keenetic_ssh('ndmc -c "show running-config" 2>&1 | grep -iE "^[[:space:]]*ip host "', timeout=timeout)
    ansi_re = re.compile(r'\x1b?\[[0-9;?]*[a-zA-Z]')
    entries = []
    for line in ansi_re.sub('', r.get("stdout", "") or "").splitlines():
        m = re.search(r'ip host\s+(\S+)\s+(\S+)', line)
        if m:
            entries.append({"host": m.group(1), "ip": m.group(2)})
    return entries, r.get("ok", False)


@app.route("/api/diagnose/site", methods=["GET"])
@requires_auth
def api_diagnose_site():
    """Послойная диагностика доступности сайта (DNS/TCP/TLS/HTTP) с точки зрения хоста
    панели — вендоренный rkn_checker. В отличие от /api/xkeen/diagnose (здоровье XKeen
    на роутере) проверяет ИМЕННО доступность доменов и тип блокировки.

    Query:
      domains=instagram.com, x.com   (запятая/пробел/перевод строки, до 12 шт)
      via=1                          дополнительно прогнать через тест-SOCKS
                                     (см. /api/xkeen/test-socks) — сравнение
                                     «текущий роутинг» vs «через выбранный outbound».
    Ответ: { ok, available, results:[...], results_via?:[...], via_outbound?, via_error? }
    """
    if not _RKN_OK:
        return jsonify({"ok": False, "available": False,
                        "error": "rkn_checker недоступен: " + _RKN_ERR}), 200
    raw = request.args.get("domains", "") or ""
    items = [x.strip() for x in re.split(r"[\s,]+", raw) if x.strip()]
    if not items:
        return jsonify({"ok": False, "available": True, "error": "Не задан домен"}), 400
    urls = {}
    for it in items[:12]:
        host = re.sub(r"^https?://", "", it, flags=re.IGNORECASE).split("/")[0]
        if not host:
            continue
        urls[host] = it if re.match(r"^https?://", it, re.IGNORECASE) else "https://" + it
    if not urls:
        return jsonify({"ok": False, "available": True, "error": "Не распознан домен"}), 400

    def _run(proxy_url=None):
        return [r.to_dict() for r in _rkn_check_urls(urls, timeout=6.0, proxy_url=proxy_url)]

    out = {"ok": True, "available": True}
    try:
        out["results"] = _run()
    except Exception as exc:  # noqa: BLE001
        return jsonify({"ok": False, "available": True, "error": repr(exc)}), 200

    # 🧭 Для каждого домена — в какой канал он попадёт ПО ПРЕСЕТАМ роутера (read-only).
    # Это «проверка настроек»: видно сразу, что напр. instagram реально в канале FOREIGN.
    # Если роутер недоступен — не критично, послойная проверка всё равно показана.
    try:
        _tg = keenetic_get_watchdog_targets()
        out["channels"] = {h: _channel_for_domain(h, _tg) for h in urls}
    except Exception:  # noqa: BLE001
        out["channels"] = None

    # 🔵 IPv6-only детект. rkn_checker сам IPv4-only (resolve_system_all=AF_INET, DoH type=A)
    # → для IPv6-only домена (есть только AAAA) выдаёт невнятное «DOWN / низкая уверенность».
    # Спрашиваем A и AAAA напрямую через DoH: если A нет, а AAAA есть = IPv6-only.
    # Такой домен с роутера (где IPv6 выключен) не открыть → предложим fake-IP (кнопка в UI).
    v6only = {}
    for h in urls:
        has_aaaa = _doh_has_records(h, "AAAA")
        if has_aaaa:
            has_a = _doh_has_records(h, "A")
            v6only[h] = (has_a is False)   # есть AAAA, A точно нет
        else:
            v6only[h] = False
    out["ipv6_only"] = v6only
    out["fake_ip"] = _FAKE_IP_FOR_V6ONLY

    # Уже стоит ли `ip host` для IPv6-only доменов — чтобы не предлагать «Сделать доступным»
    # повторно (показать «уже доступен» + кнопку «убрать»). Роутер дёргаем ТОЛЬКО если есть
    # хоть один IPv6-only домен (иначе лишний ndmc-вызов на каждую проверку).
    iphost_set = {}
    if any(v6only.values()):
        try:
            _entries, _ = _iphost_entries(timeout=15)
            _hosts = {e["host"].lower().rstrip(".") for e in _entries}
            iphost_set = {h: (h.lower().rstrip(".") in _hosts) for h in urls}
        except Exception:  # noqa: BLE001
            iphost_set = {}
    out["iphost"] = iphost_set

    if request.args.get("via"):
        proxy_url, via_tag = _test_socks_proxy_url()
        if not proxy_url:
            out["via_error"] = "Тест-узел не настроен — нажми «⚙ Подготовить узел»."
        else:
            out["via_outbound"] = via_tag
            try:
                out["results_via"] = _run(proxy_url)
            except Exception as exc:  # noqa: BLE001
                out["via_error"] = "Проверка через узел не удалась: " + repr(exc)

    # 🤖 Anti-bot fallback: для AI-сервисов с 401/403/429 — повторить через curl-cffi
    # с Chrome-fingerprint. Это отличает «реально IP в bot-defense» от «нашему
    # Python-клиенту отказали из-за TLS-fingerprint'а».
    # Делаем для каждого результата индивидуально, только если applicable.
    if _CCFFI_OK and out.get("results"):
        for r in out["results"]:
            try:
                host = r.get("name") or ""
                status = r.get("status_code")
                # Условия для probe: anti-bot домен AND отказ-статус (или статуса нет
                # вообще = network-level failure уже диагностирован, не лезем)
                if not _is_anti_bot_sensitive(host):
                    continue
                if status not in _ANTI_BOT_STATUS_CODES:
                    continue
                target_url = urls.get(host) or f"https://{host}"
                r["chrome_fp"] = _chrome_fp_probe(target_url, timeout=8)
            except Exception:  # noqa: BLE001
                # Один сбойный probe не должен валить весь ответ
                pass

    return jsonify(out)


@app.route("/api/xkeen/iphost", methods=["GET", "POST"])
@requires_auth
def api_xkeen_iphost():
    """Статический DNS-хост на Keenetic (ndm `ip host <домен> <fake-IPv4>`).

    Зачем: IPv6-only сайты (или заблокированные по IP) не открываются с роутера, где
    IPv6 выключен — клиент не получает рабочего IPv4 и соединение не доходит до xray.
    Фейковый IPv4 чинит это: клиент коннектится на него → TPROXY ловит → xray по SNI
    (sniffing http,tls) понимает домен → VPN-сервер сам резолвит реальный (IPv6) адрес.

    🛡 БЕЗОПАСНО: трогает ТОЛЬКО ndm-DNS (как `set-client-policy`), НИКОГДА не xray /
    tproxy / `xkeen -restart` → физически не может повторить инцидент Phase-2-socks.

    GET  → { ok, entries:[{host,ip}], fake_ip }
    POST → domain=<host>  action=add|remove   → ndmc `ip host` / `no ip host` + save
    """
    ansi_re = re.compile(r'\x1b?\[[0-9;?]*[a-zA-Z]')
    if request.method == "GET":
        entries, ok = _iphost_entries(timeout=25)
        return jsonify({"ok": ok, "entries": entries, "fake_ip": _FAKE_IP_FOR_V6ONLY})

    domain = (request.form.get("domain", "") or "").strip().lower().rstrip(".")
    action = (request.form.get("action", "add") or "add").strip()
    if not _IPHOST_DOMAIN_RE.match(domain):
        return jsonify({"ok": False, "error": f"Невалидный домен: {domain!r}"}), 400
    ip = _FAKE_IP_FOR_V6ONLY
    verb = "no ip host" if action == "remove" else "ip host"
    cmd = (f'ndmc -c "{verb} {domain} {ip}" 2>&1; echo "---SAVE---"; '
           f'ndmc -c "system configuration save" 2>&1')
    r = keenetic_ssh(cmd, timeout=25)
    stdout_clean = ansi_re.sub('', r.get("stdout", "") or "").strip()
    has_error = bool(re.search(r'\berror\[?\d', stdout_clean, re.IGNORECASE)) or not r["ok"]
    return jsonify({
        "ok": r["ok"] and not has_error,
        "domain": domain, "ip": ip, "action": action,
        "stdout": stdout_clean[:1500],
    })


@app.route("/api/xkeen/test-socks", methods=["GET", "POST"])
@requires_auth
def api_xkeen_test_socks():
    """Тест-SOCKS для сравнения «через outbound» (фича 🔎 Почему не работает сайт).

    GET  → { provisioned, outbound, host, port, ttl }
    POST action=remove → немедленно убрать тест-узел (rm файла + рестарт xkeen в фоне).
    POST outbound=<tag> → (пере)настроить изолированный 06_socks_test.json на роутере:
          socks-инбаунд с auth на LAN-IP роутера + правило inboundTag→outbound.
          Файл отдельный (xray confdir merge); watchdog регенерит только 05_routing.json
          и этот файл не трогает. Конфиг идёт через дашборд (а не ручной правкой).
          🛡 Узел САМОУНИЧТОЖАЕТСЯ на роутере через _TEST_SOCKS_TTL сек — диагностический
          файл не должен жить вечно (был инцидент: забытый файл ломал роутинг). См.
          _test_socks_arm_selfdestruct().
    """
    if request.method == "GET":
        user, _pw, tag = _test_socks_read()
        return jsonify({"provisioned": bool(tag), "outbound": tag,
                        "host": cfg.KEENETIC_HOST, "port": _TEST_SOCKS_PORT,
                        "ttl": _TEST_SOCKS_TTL})

    if (request.form.get("action") or "").strip() == "remove":
        _test_socks_deprovision()
        return jsonify({"ok": True, "removed": True})

    # 🚫 Фича «Сравнить через outbound» УДАЛЕНА 2026-05-23: провижининг socks-test ронял
    # household-VPN (рвал tproxy при xkeen -restart — 3 инцидента 22-23 мая). Провижининг
    # отключён наглухо. action=remove (выше) оставлен как safety-очистка забытого узла.
    return jsonify({"ok": False, "error": "Фича «Сравнить через outbound» отключена — она роняла роутерный VPN. Используй «🔎 Проверить» (диагностика с ПК)."}), 410

    target = (request.form.get("outbound") or "").strip()
    if not target:
        return jsonify({"ok": False, "error": "Не задан outbound"}), 400
    obs = keenetic_get_outbounds()
    if obs is None:
        return jsonify({"ok": False, "error": "Не смог прочитать outbounds с роутера"}), 200
    if target not in [o.get("tag") for o in obs]:
        return jsonify({"ok": False, "error": f"Outbound '{target}' не найден"}), 400

    _, old_pw, _ = _test_socks_read()
    import secrets as _secrets
    pw = old_pw or _secrets.token_urlsafe(18)
    socks_cfg = {
        "inbounds": [{
            "tag": "socks-test",
            "listen": cfg.KEENETIC_HOST,
            "port": _TEST_SOCKS_PORT,
            "protocol": "socks",
            "settings": {"auth": "password",
                         "accounts": [{"user": _TEST_SOCKS_USER, "pass": pw}],
                         "udp": False},
            "sniffing": {"enabled": True, "destOverride": ["http", "tls"]},
        }],
        "routing": {"rules": [{"type": "field",
                               "inboundTag": ["socks-test"],
                               "outboundTag": target}]},
    }
    content = json.dumps(socks_cfg, ensure_ascii=False, indent=2)
    path = _test_socks_path()
    # Бэкап эфемерного диагностического файла не нужен (он каждый раз генерится дашбордом),
    # а старые .bak-* только копятся как мусор → пишем напрямую, без cp.
    w = keenetic_ssh(f"cat > {path}", stdin_data=content, timeout=15)
    if not w["ok"]:
        return jsonify({"ok": False, "error": "Запись не удалась: " + (w.get("stderr") or "")}), 200
    test = keenetic_ssh(f'XRAY_LOCATION_ASSET=/opt/etc/xray/dat /opt/sbin/xray run -test -confdir {cfg.KEENETIC_XRAY_CONFIGS} 2>&1; echo "XRAYRC=$?"', timeout=30)
    test_out = test.get("stdout") or ""
    valid = "XRAYRC=0" in test_out  # точная проверка по коду выхода xray (не по тексту)
    if not valid:
        keenetic_ssh(f"rm -f {path}", timeout=10)
        return jsonify({"ok": False, "error": "xray run -test не прошёл — откат конфига.\n" + test_out[-600:]}), 200
    r = keenetic_ssh("xkeen -restart 2>&1 | tail -3", timeout=70)
    # 🛡 Защита от footgun'а: вооружаем самоуничтожение тест-узла на РОУТЕРЕ. Даже если юзер
    # забудет нажать «убрать», закроет вкладку или дашборд упадёт — роутер сам удалит
    # 06_socks_test.json и перезапустится через _TEST_SOCKS_TTL сек. Узел больше не способен
    # «застрять» и поломать роутинг.
    _test_socks_arm_selfdestruct()
    return jsonify({"ok": True, "outbound": target,
                    "host": cfg.KEENETIC_HOST, "port": _TEST_SOCKS_PORT,
                    "ttl": _TEST_SOCKS_TTL,
                    "restart": (r.get("stdout") or "").strip()[-300:]})


# Whitelist auto-fix-операций. Каждая — это безопасная операция с явным confirm в UI.
XKEEN_AUTO_FIXES = {
    "restart_xkeen": {
        "label": "Перезапустить xkeen",
        "explain": "xkeen -restart → xray заново стартует с текущими конфигами.",
    },
    "regen_routing": {
        "label": "Перегенерить routing.json",
        "explain": ("Запустить /opt/etc/xray/watchdog.sh → пересоберёт routing.json из template "
                    "+ свежих значений из watchdog.config. Если генерация даст битый JSON — watchdog v9+ "
                    "не применит его, старый рабочий routing останется."),
    },
    "set_primary_direct": {
        "label": "PRIMARY_TAG = direct + перегенерить",
        "explain": ("Записать в watchdog.config: PRIMARY_TAG=\"direct\". Затем запустить watchdog → "
                    "regen routing → xkeen restart. Трафик пойдёт через провайдера (direct), VPN не нужен. "
                    "Можно потом сменить через UI."),
    },
    "bootstrap_outbounds": {
        "label": "Создать direct + block outbounds",
        "explain": ("Если в 04_outbounds.json нет direct/block — добавить их в начало (existing "
                    "outbound'ы из подписки останутся нетронутыми). Это нужно для виртуального канала "
                    "«🌐 Напрямую» и для BLOCK_DOMAINS."),
    },
    "bootstrap_cron": {
        "label": "Добавить cron-задачу watchdog",
        "explain": ("Добавить запись `*/1 * * * * /opt/etc/xray/watchdog.sh` в crontab. Watchdog будет "
                    "проверять каналы каждую минуту и переключаться при падении."),
    },
    "install_extended_geoip": {
        "label": "Установить расширенный geoip.dat (Loyalsoldier)",
        "explain": (
            "Скачать с github.com/Loyalsoldier/v2ray-rules-dat расширенный geoip.dat (~18MB) — он "
            "содержит категории сервисов (telegram, discord и др.) в дополнение к странам. "
            "Стандартный v2fly geoip.dat и XKeen-installer ставят только страны — этого недостаточно "
            "для геоблокировки конкретных сервисов. Текущий файл (если есть) будет сохранён как "
            "geoip.dat.bak-<timestamp>. После скачивания xkeen перезапустится автоматически."
        ),
    },
    "install_libnghttp2": {
        "label": "Переустановить libnghttp2 (фикс curl)",
        "explain": (
            "opkg update + opkg install libnghttp2 --force-reinstall. Чинит сломанный curl "
            "из-за отсутствия libnghttp2.so.14. После фикса xkeen-installer снова сможет проверять "
            "политику XKeen через RCI и xkeen -restart будет работать корректно."
        ),
    },
    "install_entware_tar": {
        "label": "Установить Entware GNU tar (для миграции)",
        "explain": (
            "opkg install tar. Системный BusyBox-tar не поддерживает --exclude= и плохо ест списки "
            "файлов через $(). Entware-пакет ставит полноценный GNU tar в /opt/bin/tar — он совместим "
            "с XKeen-документацией для миграции через entware_backup.tar.gz."
        ),
    },
}


@app.route("/api/xkeen/auto-fix", methods=["POST"])
@requires_auth
def api_xkeen_auto_fix():
    """Выполнить конкретный auto-fix. Body: fix_id=<ID из XKEEN_AUTO_FIXES>.
    Возвращает: { ok, fix_id, label, log: "..." }
    """
    fix_id = request.form.get("fix_id", "").strip()
    if fix_id not in XKEEN_AUTO_FIXES:
        return jsonify({"ok": False, "error": f"Unknown fix_id '{fix_id}'. Allowed: {list(XKEEN_AUTO_FIXES.keys())}"}), 400

    fix = XKEEN_AUTO_FIXES[fix_id]
    log_lines = [f"🔧 Применяю fix: {fix['label']}"]

    if fix_id == "restart_xkeen":
        r = keenetic_ssh("xkeen -restart 2>&1 | tail -10", timeout=90)
        ansi_re = re.compile(r'\x1b\[[0-9;?]*[a-zA-Z]')
        log_lines.append(ansi_re.sub('', r.get("stdout") or "") or "(empty)")
        # Проверка статуса
        r2 = keenetic_ssh("xkeen -status 2>&1", timeout=10)
        status = ansi_re.sub('', (r2.get("stdout") or "") + (r2.get("stderr") or ""))
        log_lines.append("---")
        log_lines.append(status)
        ok = "запущен" in status and "не запущен" not in status

    elif fix_id == "regen_routing":
        r = keenetic_ssh("/opt/etc/xray/watchdog.sh 2>&1 | tail -10", timeout=30)
        log_lines.append((r.get("stdout") or "") or "(watchdog отработал тихо)")
        # Тест конфига после
        r2 = keenetic_ssh("XRAY_LOCATION_ASSET=/opt/etc/xray/dat /opt/sbin/xray run -test -confdir /opt/etc/xray/configs 2>&1 | tail -5", timeout=15)
        log_lines.append("---")
        log_lines.append(r2.get("stdout") or "")
        ok = "Configuration OK" in (r2.get("stdout") or "")

    elif fix_id == "set_primary_direct":
        # Проверка что direct есть в outbounds — иначе нет смысла
        r0 = keenetic_ssh("grep -c '\"tag\": *\"direct\"' /opt/etc/xray/configs/04_outbounds.json 2>/dev/null", timeout=5)
        has_direct = (r0.get("stdout") or "0").strip() not in ("0", "")
        if not has_direct:
            log_lines.append("⚠ direct outbound отсутствует в 04_outbounds.json — сначала применить bootstrap_outbounds")
            ok = False
        else:
            r1 = keenetic_ssh("sed -i 's/^PRIMARY_TAG=.*/PRIMARY_TAG=\"direct\"/' /opt/etc/xray/watchdog.config && grep '^PRIMARY_TAG=' /opt/etc/xray/watchdog.config", timeout=5)
            log_lines.append(r1.get("stdout") or "")
            r2 = keenetic_ssh("/opt/etc/xray/watchdog.sh 2>&1 | tail -5", timeout=30)
            log_lines.append("---")
            log_lines.append(r2.get("stdout") or "(watchdog отработал тихо)")
            ok = r1["ok"] and r2["ok"]

    elif fix_id == "bootstrap_outbounds":
        # Через bootstrap-deploy одной item — outbounds_defaults со спец-логикой
        # (если outbounds[] пусто — применит дефолт direct+block; если уже что-то есть — не тронет)
        state = _bootstrap_collect_state()
        item = next((it for it in state.get("items", []) if it["key"] == "outbounds_defaults"), None)
        if not item:
            ok = False
            log_lines.append("❌ Не найден item 'outbounds_defaults' в bootstrap state")
        else:
            result = _bootstrap_deploy_item(item, overwrite_existing=False)
            log_lines.append(result.get("msg", "(no msg)"))
            ok = result.get("ok", False)

    elif fix_id == "bootstrap_cron":
        cron_line = "*/1 * * * * /opt/etc/xray/watchdog.sh"
        cron_cmd = (
            "(crontab -l 2>/dev/null | grep -vF '/opt/etc/xray/watchdog.sh'; "
            f"echo '{cron_line}') | crontab -"
        )
        r = keenetic_ssh(cron_cmd, timeout=10)
        # Verify
        r2 = keenetic_ssh("crontab -l 2>/dev/null | grep -F '/opt/etc/xray/watchdog.sh'", timeout=5)
        added = bool((r2.get("stdout") or "").strip())
        log_lines.append(f"crontab после fix: {r2.get('stdout') or '(пусто!)'}")
        ok = added

    elif fix_id == "install_extended_geoip":
        # Скачивает Loyalsoldier geoip.dat (содержит и страны, и сервисы).
        # 1. Backup существующего geoip.dat (если есть) → .bak-<timestamp>
        # 2. curl -kL → новый geoip.dat
        # 3. xkeen -restart → xray перечитает routing с новой базой
        ansi_re = re.compile(r'\x1b\[[0-9;?]*[a-zA-Z]')
        ts = datetime.now().strftime("%Y%m%d-%H%M%S")
        # Объединённая команда: backup + download + size check
        download_cmd = (
            f"if [ -f /opt/etc/xray/dat/geoip.dat ]; then "
            f"  cp /opt/etc/xray/dat/geoip.dat /opt/etc/xray/dat/geoip.dat.bak-{ts}; "
            f"  echo \"Backup: geoip.dat.bak-{ts}\"; "
            f"fi; "
            f"rm -f /opt/etc/xray/dat/geoip.dat; "
            f"curl -kL --max-time 120 -o /opt/etc/xray/dat/geoip.dat "
            f"https://github.com/Loyalsoldier/v2ray-rules-dat/releases/latest/download/geoip.dat 2>&1 | tail -3; "
            f"ls -la /opt/etc/xray/dat/geoip.dat 2>&1"
        )
        r = keenetic_ssh(download_cmd, timeout=180)
        out = ansi_re.sub('', r.get("stdout") or "") + ansi_re.sub('', r.get("stderr") or "")
        log_lines.append(out or "(empty)")

        # Проверка что файл скачался и имеет разумный размер (> 1MB)
        size_check = keenetic_ssh(
            "wc -c < /opt/etc/xray/dat/geoip.dat 2>/dev/null",
            timeout=5,
        )
        try:
            file_size = int((size_check.get("stdout") or "0").strip())
        except (ValueError, AttributeError):
            file_size = 0

        if file_size < 1024 * 1024:
            log_lines.append(f"❌ Файл geoip.dat не скачался или слишком маленький ({file_size} байт)")
            log_lines.append("   Возможно нет интернета на роутере или GitHub недоступен.")
            ok = False
        else:
            log_lines.append(f"✅ geoip.dat скачан: {file_size} байт ({file_size // 1024 // 1024} MB)")
            # Перезапуск xkeen чтобы xray перечитал
            r2 = keenetic_ssh("xkeen -restart 2>&1 | tail -8", timeout=90)
            log_lines.append("---")
            log_lines.append(ansi_re.sub('', r2.get("stdout") or "") or "(empty)")
            # Status check
            r3 = keenetic_ssh("xkeen -status 2>&1", timeout=10)
            status = ansi_re.sub('', (r3.get("stdout") or "") + (r3.get("stderr") or ""))
            log_lines.append("---")
            log_lines.append(status)
            # ok если xray запущен. v1.7.17: Mixed/TPROXY/Redirect — все валидные режимы
            # работы XKeen, не маркер ошибки. Раньше считал Mixed как failure но юзер
            # подтвердил через checkip.amazonaws.com что VPN полностью работает в Mixed-режиме.
            # Реальный показатель ошибки загрузки категории — failed to load в error.log.
            is_running = "запущен" in status and "не запущен" not in status
            # Доп. проверка: в error.log не должно быть свежих "failed to load" про geoip/geosite
            r4 = keenetic_ssh("tail -50 /opt/var/log/xray/error.log 2>/dev/null | grep -iE 'failed to load|cannot find|no such file' | tail -5", timeout=5)
            load_errors = (r4.get("stdout") or "").strip()
            if is_running and not load_errors:
                ok = True
                # Информационное сообщение про режим (без флага ошибки)
                if "Mixed" in status:
                    log_lines.append("ℹ️ xkeen в режиме Mixed — это валидный режим работы (один из трёх: TPROXY/Mixed/Redirect). VPN работает. Проверить можно через https://checkip.amazonaws.com — должен показать IP VPN-сервера, не твоего провайдера.")
                elif "TPROXY" in status:
                    log_lines.append("ℹ️ xkeen в режиме TPROXY — оптимальный режим.")
            elif is_running and load_errors:
                log_lines.append("⚠ xray запущен, но в error.log есть ошибки загрузки категорий:")
                log_lines.append(load_errors)
                log_lines.append("Возможно ещё какая-то категория отсутствует в geoip.dat / geosite.dat.")
                ok = False
            else:
                log_lines.append("❌ xray не запустился после установки. Проверь /opt/var/log/xray/error.log на роутере.")
                ok = False

    elif fix_id == "install_libnghttp2":
        ansi_re = re.compile(r'\x1b\[[0-9;?]*[a-zA-Z]')
        # opkg update + force-reinstall libnghttp2 — может потребоваться ~30 сек на скачивание Packages.gz
        r1 = keenetic_ssh("opkg update 2>&1 | tail -5", timeout=60)
        log_lines.append(ansi_re.sub('', r1.get("stdout") or "") or "(opkg update тих)")
        log_lines.append("---")
        r2 = keenetic_ssh("opkg install libnghttp2 --force-reinstall 2>&1 | tail -10", timeout=60)
        log_lines.append(ansi_re.sub('', r2.get("stdout") or "") or "(opkg install тих)")
        log_lines.append("---")
        # Проверка что curl снова работает
        r3 = keenetic_ssh("curl --version 2>&1 | head -1", timeout=10)
        curl_ok_now = r3["ok"] and "curl" in (r3.get("stdout") or "") and "shared libraries" not in (r3.get("stdout") or "") + (r3.get("stderr") or "")
        log_lines.append(f"curl --version: {r3.get('stdout', '').strip()[:120] or r3.get('stderr', '')[:120]}")
        if curl_ok_now:
            log_lines.append("✅ curl восстановлен. xkeen-installer теперь сможет проверить политику через RCI.")
        else:
            log_lines.append("⚠ curl всё ещё не работает — возможно сломаны ещё библиотеки (libcurl, libssl). Попробуй вручную: opkg install curl --force-reinstall")
        ok = curl_ok_now

    elif fix_id == "install_entware_tar":
        ansi_re = re.compile(r'\x1b\[[0-9;?]*[a-zA-Z]')
        r1 = keenetic_ssh("opkg update 2>&1 | tail -3", timeout=60)
        log_lines.append(ansi_re.sub('', r1.get("stdout") or "") or "(opkg update тих)")
        log_lines.append("---")
        r2 = keenetic_ssh("opkg install tar 2>&1 | tail -5", timeout=60)
        log_lines.append(ansi_re.sub('', r2.get("stdout") or "") or "(opkg install тих)")
        log_lines.append("---")
        r3 = keenetic_ssh("/opt/bin/tar --version 2>&1 | head -1", timeout=5)
        tar_ok = r3["ok"] and "tar" in (r3.get("stdout") or "")
        log_lines.append(f"/opt/bin/tar --version: {r3.get('stdout', '').strip()[:120] or r3.get('stderr', '')[:120]}")
        if tar_ok:
            log_lines.append("✅ Entware GNU tar установлен. Кнопка миграции теперь будет использовать его.")
        else:
            log_lines.append("⚠ /opt/bin/tar не появился. Проверь вывод opkg выше — возможно нет интернета на роутере.")
        ok = tar_ok

    else:
        ok = False
        log_lines.append(f"❌ Логика fix '{fix_id}' не реализована")

    return jsonify({
        "ok": ok,
        "fix_id": fix_id,
        "label": fix["label"],
        "log": "\n".join(log_lines),
    })


@app.route("/api/xkeen/dat-categories", methods=["GET"])
@requires_auth
def api_xkeen_dat_categories():
    """Информация о доступных категориях geosite/geoip + КУДА они применяются в routing.

    Возвращает:
      - usage: [{full, dat, category, outbound_tag, desc, source}] — категории используемые
        в реальном routing.json + template, с указанием outboundTag (куда трафик идёт).
      - known: статичный список топ-категорий v2fly с описаниями (для подсказки).
      - dat_files: список .dat файлов на роутере с размерами и mtime.
    """
    # Map категорий → описание из known-списка
    desc_by_name = {c["name"]: c["desc"] for c in V2FLY_KNOWN_CATEGORIES}

    # Парсер JSON с комментариями — XKeen 05_routing.json начинается с // комментариями.
    # Удаляем строки начинающиеся с //, потом стандартный json.loads.
    import re as _re_local
    def _strip_json_comments(text_):
        return _re_local.sub(r'^\s*//.*$', '', text_, flags=_re_local.MULTILINE)

    def _scan_rules_file(remote_path, source_label):
        """Читает routing-файл с роутера, находит rules с ext:... ссылками.
        Возвращает list of dicts: {full, dat, category, outbound_tag, source, rule_index}."""
        raw = keenetic_read_file(remote_path)
        if not raw:
            return []
        try:
            cleaned = _strip_json_comments(raw)
            data_ = json.loads(cleaned)
        except Exception:
            return []
        result = []
        rules = (data_.get("routing", {}) or {}).get("rules", []) or []
        for idx, rule in enumerate(rules):
            outbound = rule.get("outboundTag") or "(default)"
            for field in ("domain", "ip"):
                arr = rule.get(field, []) or []
                if not isinstance(arr, list):
                    continue
                for item in arr:
                    if isinstance(item, str) and item.startswith("ext:"):
                        parts = item.split(":")
                        if len(parts) >= 3:
                            result.append({
                                "full": item,
                                "dat": parts[1],
                                "category": parts[2],
                                "outbound_tag": outbound,
                                "source": source_label,
                                "rule_index": idx,
                                "field": field,
                            })
        return result

    # Приоритет: фактический 05_routing.json (то что Xray сейчас исполняет).
    # Если нет — template (для понимания что watchdog будет генерить).
    usage = _scan_rules_file(f"{cfg.KEENETIC_XRAY_CONFIGS}/05_routing.json", "routing.json")
    if not usage:
        usage = _scan_rules_file(f"{cfg.KEENETIC_XRAY_BAK_DIR}/05_routing.template.json", "template")

    # Добавляем описание категории из known-списка (если есть)
    for u in usage:
        u["desc"] = desc_by_name.get(u["category"], "")

    # in_use — обратная совместимость со старым UI (просто список ext:... без outbound)
    in_use = [{"full": u["full"], "dat": u["dat"], "category": u["category"]} for u in usage]

    # .dat файлы на роутере: имя, размер, mtime (для отображения «когда обновлялись»)
    r = keenetic_ssh(
        "for f in /opt/etc/xray/dat/*.dat; do "
        "  size=$(wc -c < \"$f\" 2>/dev/null || echo 0); "
        "  mtime=$(date -r \"$f\" \"+%Y-%m-%d %H:%M\" 2>/dev/null || echo \"?\"); "
        "  echo \"$size|$mtime|$(basename $f)\"; "
        "done 2>/dev/null",
        timeout=8
    )
    dat_files = []
    if r["ok"] and r["stdout"]:
        for line in r["stdout"].strip().split("\n"):
            parts = line.split("|", 2)
            if len(parts) == 3:
                try:
                    size = int(parts[0])
                    dat_files.append({
                        "name": parts[2],
                        "size": size,
                        "size_mb": round(size / 1024 / 1024, 2),
                        "mtime": parts[1],
                    })
                except ValueError:
                    pass

    return jsonify({
        "ok": True,
        "usage": usage,
        "in_use": in_use,
        "known": V2FLY_KNOWN_CATEGORIES,
        "dat_files": dat_files,
        "note": "Полный список категорий: https://github.com/v2fly/domain-list-community/tree/master/data",
    })


# ──────────────────────────────────────────────────────────────────────────
# DAT lookup — поиск домена/IP по СОДЕРЖИМОМУ .dat-файлов на роутере.
# Дополняет /api/xkeen/dat-categories (которая показывает обратное: где
# категории применяются в routing.json). Сначала синхронизирует локальный кэш
# с роутером (по mtime), затем парсит и ищет полностью локально.
# Парсер — geosite_scanner.py (protobuf low-level decode, без зависимостей).
# ──────────────────────────────────────────────────────────────────────────

def _dat_sync_files(cache, want_kind=None, force=False):
    """Синхронизировать локальный кэш с роутером для нужного типа (geosite/geoip).

    want_kind: 'geosite' | 'geoip' | None (любой).
    force: всегда перекачать.
    Возвращает (synced: [files], errors: [{file, reason}]).
    """
    remote = _list_remote_dat()
    if not remote:
        return [], [{"file": "*", "reason": "Роутер недоступен или /opt/etc/xray/dat пуст"}]
    synced = []
    errors = []
    for entry in remote:
        name = entry["name"]
        # эвристика по имени файла — пропускаем нерелевантный тип
        lname = name.lower()
        if want_kind == "geosite" and "geoip" in lname:
            continue
        if want_kind == "geoip" and "geosite" in lname:
            continue
        # zkeen.dat — geosite, zkeenip.dat — geoip (по имени)
        if want_kind == "geosite" and lname == "zkeenip.dat":
            continue
        if want_kind == "geoip" and lname == "zkeen.dat":
            continue
        local = cache.ensure(name, remote_mtime=entry["mtime"], force=force)
        if local:
            synced.append(name)
        else:
            errors.append({"file": name, "reason": "не удалось скачать"})
    return synced, errors


@app.route("/api/xkeen/dat/lookup", methods=["GET"])
@requires_auth
def api_xkeen_dat_lookup():
    """Поиск домена/IP по СОДЕРЖИМОМУ geosite/geoip .dat-файлов.

    Query:
      target: домен или IP (обязательно).
      kind:   'auto' (default) | 'domain' | 'ip' — override авто-детекции.

    Returns:
      ok: bool
      target, type: что искали и в каких файлах (geosite vs geoip)
      results: [{file, size, mtime, categories: [str], ext_refs: [str]}]
      errors:  [{file, reason}] — что не получилось скачать/распарсить
      elapsed_ms: чистое время поиска
    """
    if not _GEOSITE_OK:
        return jsonify({"ok": False, "error": f"geosite_scanner не доступен: {_GEOSITE_ERR}"}), 503
    target = (request.args.get("target") or "").strip()
    if not target:
        return jsonify({"ok": False, "error": "Параметр target обязателен"}), 400
    kind = (request.args.get("kind") or "auto").lower()

    # Авто-детект domain vs IP
    if kind == "auto":
        try:
            import ipaddress as _ipa
            _ipa.ip_address(target)
            kind = "ip"
        except ValueError:
            kind = "domain"
    if kind not in ("domain", "ip"):
        return jsonify({"ok": False, "error": "kind должен быть auto|domain|ip"}), 400

    cache = _get_dat_cache()
    if not cache:
        return jsonify({"ok": False, "error": "DatCache не инициализирован"}), 503

    want_kind = "geosite" if kind == "domain" else "geoip"
    t0 = _time_mod.time()
    synced, errors = _dat_sync_files(cache, want_kind=want_kind, force=False)

    results = []
    for filename in synced:
        local_path = cache.local_path(filename)
        try:
            detected = _geosite_scanner.detect_dat_type(local_path)
        except Exception as ex:  # noqa: BLE001
            errors.append({"file": filename, "reason": f"detect failed: {ex}"})
            continue
        if detected != want_kind:
            continue  # скип несовпадающего типа (страховка от эвристики по имени)
        try:
            if kind == "domain":
                cats = _geosite_scanner.lookup_domain(local_path, target)
            else:
                cats = _geosite_scanner.lookup_ip(local_path, target)
        except Exception as ex:  # noqa: BLE001
            errors.append({"file": filename, "reason": f"lookup failed: {ex}"})
            continue
        # Нормализуем категории к lowercase (xray-core case-insensitive,
        # в наших правилах routing.json — обычно lower)
        cats_lc = sorted({c.lower() for c in cats})
        if not cats_lc:
            continue
        try:
            st = os.stat(local_path)
            size, mtime = st.st_size, int(st.st_mtime)
        except OSError:
            size, mtime = 0, 0
        results.append({
            "file": filename,
            "size": size,
            "mtime": mtime,
            "categories": cats_lc,
            "ext_refs": [f"ext:{filename}:{c}" for c in cats_lc],
        })

    elapsed = int((_time_mod.time() - t0) * 1000)
    # Собираем descriptions всех уникальных категорий (для tooltip'ов в UI)
    all_cats = set()
    for r in results:
        for c in r.get("categories", []):
            all_cats.add(c)
    descriptions = {c: V2FLY_DESC_BY_NAME[c] for c in all_cats if c in V2FLY_DESC_BY_NAME}
    return jsonify({
        "ok": True,
        "target": target,
        "type": kind,
        "results": results,
        "errors": errors,
        "elapsed_ms": elapsed,
        "category_descriptions": descriptions,
    })


@app.route("/api/xkeen/dat/refresh-cache", methods=["POST"])
@requires_auth
def api_xkeen_dat_refresh():
    """Принудительно перекачать .dat-кэш с роутера.

    Body (опц.): {"files": ["name1.dat", ...]} — конкретные файлы. Пусто = все.
    Returns: {ok, refreshed: [names], errors: [{file, reason}]}
    """
    if not _GEOSITE_OK:
        return jsonify({"ok": False, "error": f"geosite_scanner не доступен: {_GEOSITE_ERR}"}), 503
    cache = _get_dat_cache()
    if not cache:
        return jsonify({"ok": False, "error": "DatCache не инициализирован"}), 503
    body = request.get_json(silent=True) or {}
    requested = body.get("files") or []
    remote = _list_remote_dat()
    if not remote:
        return jsonify({"ok": False, "error": "Роутер недоступен"}), 503

    refreshed = []
    errors = []
    targets = remote if not requested else [e for e in remote if e["name"] in requested]
    for entry in targets:
        local = cache.ensure(entry["name"], remote_mtime=entry["mtime"], force=True)
        if local:
            refreshed.append(entry["name"])
        else:
            errors.append({"file": entry["name"], "reason": "не удалось скачать"})
    return jsonify({"ok": True, "refreshed": refreshed, "errors": errors})


@app.route("/api/xkeen/dat/cache-status", methods=["GET"])
@requires_auth
def api_xkeen_dat_cache_status():
    """Состояние локального кэша + текущее состояние на роутере + diff.

    Returns:
      ok: bool
      cached:  [{name, size, mtime}, ...] — что в локальном кэше
      remote:  [{name, size, mtime}, ...] — что сейчас на роутере (если доступен)
      stale:   [name] — файлы, локальный кэш которых устарел
      missing: [name] — файлы на роутере без локального кэша
    """
    if not _GEOSITE_OK:
        return jsonify({"ok": False, "error": f"geosite_scanner не доступен: {_GEOSITE_ERR}"}), 503
    cache = _get_dat_cache()
    if not cache:
        return jsonify({"ok": False, "error": "DatCache не инициализирован"}), 503

    cached = cache.cached_files()
    cached_by_name = {f["name"]: f for f in cached}

    remote = _list_remote_dat()  # пустой если роутер недоступен — это ок
    remote_by_name = {f["name"]: f for f in remote}

    stale = []
    missing = []
    for name, ri in remote_by_name.items():
        ci = cached_by_name.get(name)
        if not ci:
            missing.append(name)
            continue
        if ci["mtime"] < ri["mtime"]:
            stale.append(name)

    return jsonify({
        "ok": True,
        "cached": cached,
        "remote": remote,
        "stale": stale,
        "missing": missing,
        "cache_dir": cache.cache_dir,
    })


